from common import *
import openpyxl,collections,time
start=time.time();w=openpyxl.load_workbook(SPEED,read_only=True,data_only=True);ws=w.worksheets[0];it=ws.iter_rows(values_only=True);header=list(next(it));dates=collections.Counter();links=collections.defaultdict(set);date_link=collections.Counter();missing=collections.Counter();numeric=collections.Counter();meta=collections.defaultdict(lambda:collections.defaultdict(set));n=0
