for lid,values in meta.items():
 d={'service_link':lid}
 for k,val in values.items():d[k+'_values_json']=json.dumps(sorted(val),ensure_ascii=False)
 d['metadata_definition_variants']=max(map(len,values.values()));roads.append(d)
roads=pd.DataFrame(roads);save(roads,'speed_service_link_registry.csv');save(mm,'service_standard_link_crosswalk.csv')
map_service=set(mm.service_link);speed_service=set(meta);std=set(mm.standard_link);by=mm.groupby('service_link').standard_link.nunique();reverse=mm.groupby('standard_link').service_link.nunique();both=speed_service&map_service
rows=[{'category':'speed_schema','metric':'columns','value':len(header),'detail':json.dumps(header,ensure_ascii=False)}, {'category':'speed_schema','metric':'rows','value':n,'detail':ws.title},{'category':'speed_schema','metric':'unique_dates','value':len(dates),'detail':json.dumps(sorted(dates))},{'category':'speed_schema','metric':'unique_service_links','value':len(speed_service),'detail':'raw column 링크아이디'},{'category':'speed_schema','metric':'duplicate_date_link_keys','value':sum(v-1 for v in date_link.values() if v>1),'detail':'key=일자+링크아이디'},{'category':'speed_schema','metric':'hour_fields','value':24,'detail':'~01시 through ~24시; source uses endpoint labels'},{'category':'time_alignment','metric':'slot_mapping_status','value':'CONDITIONAL','detail':'~01시->00~01, ... ~24시->23~24 is a candidate interpretation; interval/timezone documentation absent in file'},{'category':'units','metric':'speed_unit','value':'not_explicit_in_workbook','detail':'Do not certify km/h solely from filename; unit/codebook confirmation required'},{'category':'units','metric':'distance_unit','value':'not_explicit_in_workbook','detail':'Raw field 거리 retained; not treated as validated bus-segment length'},{'category':'mapping_schema','metric':'rows','value':len(mm),'detail':json.dumps(list(mm.columns))},{'category':'mapping_schema','metric':'service_links','value':len(map_service),'detail':''},{'category':'mapping_schema','metric':'standard_links','value':len(std),'detail':''},{'category':'mapping_schema','metric':'service_link_order_duplicate_rows','value':int(mm.duplicated(['service_link','standard_link_order']).sum()),'detail':''},{'category':'speed_mapping','metric':'service_links_matched','value':len(both),'detail':'exact service ID, not nearest-road matching'},{'category':'speed_mapping','metric':'service_links_unmatched','value':len(speed_service-map_service),'detail':json.dumps(sorted(speed_service-map_service))},{'category':'speed_mapping','metric':'speed_links_mapping_one_to_one','value':int(by.reindex(sorted(both)).eq(1).sum()),'detail':'service->standard link count, not bus->road'},{'category':'speed_mapping','metric':'speed_links_mapping_one_to_many','value':int(by.reindex(sorted(both)).gt(1).sum()),'detail':'service->standard link count, not bus->road'},{'category':'mapping_schema','metric':'standard_links_multiple_service_owners','value':int(reverse.gt(1).sum()),'detail':'many service links can share a standard link'},{'category':'geometry','metric':'link_geometry_present','value':False,'detail':'speed and mapping tables have no road polyline or endpoint coordinates'},{'category':'geometry','metric':'bus_ROUTE_ID_NODE_ID_key_present','value':False,'detail':'link IDs and bus stop/route IDs are different key systems'}]
for h in header[12:]:rows.append({'category':'hour_structure','metric':h,'value':numeric[h],'detail':json.dumps({'blank':missing[h],'rows':n,'field_label':h},ensure_ascii=False)})
for d,c in sorted(dates.items()):rows.append({'category':'date_coverage','metric':d,'value':c,'detail':'Actual worksheet date, not inferred from filename'})
save(pd.DataFrame(rows),'road_speed_schema_audit.csv');dump({'header':header,'rows':n,'dates':dict(dates),'service_links':len(speed_service),'mapped_service_links':len(both),'unmapped_service_links':len(speed_service-map_service),'mapping_one_to_one':int(by.reindex(sorted(both)).eq(1).sum()),'mapping_one_to_many':int(by.reindex(sorted(both)).gt(1).sum()),'date_link_duplicate_extra_rows':sum(v-1 for v in date_link.values() if v>1),'speed_service_IDs':sorted(speed_service),'elapsed_seconds':round(time.time()-start,1)},'speed_audit_summary.json')
